package com.hostelcare.controller;
import com.hostelcare.entity.*; import java.util.*;
public final class ViewMapper { private ViewMapper(){} public static Map<String,Object> user(User u){Map<String,Object> m=new LinkedHashMap<>();m.put("userId",u.userId);m.put("name",u.name);m.put("email",u.email);m.put("phone",u.phone);m.put("role",u.role);m.put("active",u.active);m.put("room",u.room==null?null:room(u.room));return m;} public static Map<String,Object> room(Room r){return Map.of("roomId",r.roomId,"roomNumber",r.roomNumber,"floor",r.floor==null?0:r.floor,"hostel",r.hostel.hostelName,"hostelId",r.hostel.hostelId,"blockName",r.hostel.blockName==null?"":r.hostel.blockName);} public static Map<String,Object> complaint(Complaint c){Map<String,Object> m=new LinkedHashMap<>();m.put("complaintId",c.complaintId);m.put("title",c.title);m.put("description",c.description);m.put("status",c.status);m.put("priority",c.priority);m.put("category",c.category.categoryName);m.put("categoryId",c.category.categoryId);m.put("student",user(c.student));m.put("room",room(c.room));m.put("createdAt",c.createdAt);m.put("updatedAt",c.updatedAt);return m;} public static Map<String,Object> category(Category c){return Map.of("categoryId",c.categoryId,"categoryName",c.categoryName,"description",c.description==null?"":c.description);} public static Map<String,Object> hostel(Hostel h){return Map.of("hostelId",h.hostelId,"hostelName",h.hostelName,"blockName",h.blockName==null?"":h.blockName,"address",h.address==null?"":h.address);} }
